import { cpSync, mkdirSync, rmSync } from "node:fs";
import { fileURLToPath } from "node:url";
const at = (path) => fileURLToPath(new URL(path, import.meta.url));
// These directories were generated by the previous Full preview distribution.
// Keep the separate Vditor runtime used by editable Markdown.
for (const path of [
  "file-viewer",
  "wasm",
  "flyfish-viewer-assets.json",
  ...["xlsx", "pdf", "libarchive", "chm", "pptx", "ppt", "docx"].map(
    (name) => `vendor/${name}`,
  ),
]) {
  rmSync(at(`../public/${path}`), { recursive: true, force: true });
}
for (const name of ["standard", "ppt"]) {
  const destination = at(`../public/file-viewer/licenses/${name}`);
  mkdirSync(destination, { recursive: true });
  for (const file of ["LICENSE", "viewer/THIRD_PARTY_LICENSES.assets.json"])
    cpSync(
      at(`../node_modules/@file-viewer/assets-${name}/${file}`),
      `${destination}/${file.split("/").pop()}`,
    );
}
